add_action( 'before_woocommerce_pay', 'perfectpixel_order_pay_addresses' );

function perfectpixel_order_pay_addresses() {
	$order_id = absint( get_query_var( 'order-pay' ) );
	$order    = $order_id ? wc_get_order( $order_id ) : false;
	$key      = isset( $_GET['key'] ) ? wc_clean( wp_unslash( $_GET['key'] ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification

	if ( ! $order || ! hash_equals( $order->get_order_key(), $key ) ) {
		return;
	}
	if ( $order->get_customer_id() && get_current_user_id() !== $order->get_customer_id() ) {
		return;
	}

	echo '<section class="woocommerce-customer-details"><div class="woocommerce-columns woocommerce-columns--2 col2-set addresses">';
	echo '<div class="woocommerce-column col-1"><h2>' . esc_html__( 'Billing address', 'woocommerce' ) . '</h2><address>' . wp_kses_post( $order->get_formatted_billing_address( esc_html__( 'N/A', 'woocommerce' ) ) ) . '</address></div>';
	if ( $order->needs_shipping_address() ) {
		echo '<div class="woocommerce-column col-2"><h2>' . esc_html__( 'Shipping address', 'woocommerce' ) . '</h2><address>' . wp_kses_post( $order->get_formatted_shipping_address( esc_html__( 'N/A', 'woocommerce' ) ) ) . '</address></div>';
	}
	echo '</div></section>';
}
